const list = $('Find Pending Permits').first().json.pending || [];
const rows = list.map(p => {
  const badge = {
    overdue: '<span style="background:#dc2626;color:white;padding:2px 6px;border-radius:3px">VENCIDO</span>',
    due_soon: '<span style="background:#f59e0b;color:white;padding:2px 6px;border-radius:3px">PROXIMO</span>',
    stale_check: '<span style="background:#6b7280;color:white;padding:2px 6px;border-radius:3px">SIN REVISAR</span>',
    normal: '<span style="background:#10b981;color:white;padding:2px 6px;border-radius:3px">OK</span>'
  }[p.priority] || '';
  const overdueText = p.days_overdue !== null && p.days_overdue !== undefined
    ? (p.days_overdue > 0 ? '+' + Math.round(p.days_overdue) + 'd' : Math.round(-p.days_overdue) + 'd para vencer')
    : '-';
  const url = p.status_url ? '<a href="' + p.status_url + '">sede</a>' : '-';
  return '<tr><td>' + badge + '</td><td>' + (p.project_name || '?') + '</td><td>' + p.entity + '</td><td>' + p.application_type + '</td><td>' + (p.expediente_id || '-') + '</td><td>' + p.status + '</td><td>' + overdueText + '</td><td>' + Math.round(p.days_since_check || 0) + 'd</td><td>' + url + '</td></tr>';
}).join('');
const html = '<h2>Expedientes administrativos pendientes</h2>' +
  '<p>Total: ' + list.length + ' expedientes activos.</p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
  '<thead><tr style="background:#f3f4f6"><th>Estado</th><th>Proyecto</th><th>Entidad</th><th>Tipo</th><th>Expediente</th><th>Estado actual</th><th>Vencimiento</th><th>Sin revisar</th><th>Sede</th></tr></thead>' +
  '<tbody>' + rows + '</tbody></table>' +
  '<p style="font-size:12px;color:#6b7280;margin-top:16px">Actualiza un expediente: POST /webhook/permit-update con {permit_id, new_status, notes}</p>';
return [{ json: { html_body: html, count: list.length } }];

